			Task Iir(GameServer0X2000Opcodes iir, params byte[] body)
			{
				return new PacketStream().WriteHeader(sender, receiver, GameInterfaceDispatchOpcodes.DispatchPassBlob).WriteArrayUInt32Length(s => s.WriteUInt32(iir).WriteArray(body)).SendAsync(client);
			}

			// Emits a SimpleDynel scene-prop record, substituting the DB-sourced build for the verbatim bytes when
			// the row reproduces it exactly (see LoadEditorSceneDynels / the comment above).
			Task IirDynel(params byte[] verbatim)
			{
				return Iir(GameServer0X2000Opcodes.SimpleDynelFullUpdateIIR, BuildSceneDynel(dynelRows, verbatim));
			}

			// Emits a SimpleChar scene-pedestal record, RECONSTRUCTED from its own bytes (transform + identity
			// rebuilt, pre-IIR scaffold carried, session playfield threaded - CreateEditorCharBuilder). The live
			// "Character..." preview stays on IirId (it carries the live client instance as its handle).
			Task IirChar(params byte[] verbatim)
			{
				return Iir(GameServer0X2000Opcodes.SimpleCharFullUpdateIIR, CreateEditorCharBuilder.Reconstruct(verbatim, CreateEditorCharBuilder.EditorPlayfieldInstance));
			}

			Task IirId(GameServer0X2000Opcodes iir, byte[] prefix, params byte[] suffix)
			{
				return new PacketStream().WriteHeader(sender, receiver, GameInterfaceDispatchOpcodes.DispatchPassBlob).WriteArrayUInt32Length(s => s.WriteUInt32(iir).WriteArray(prefix).WriteUInt32(id).WriteArray(suffix)).SendAsync(client);
			}
		}

		// Returns the SimpleDynel record to send: the DB-sourced build (re-addressed to the verbatim record's handle
		// + the editor session playfield) when a row matches by identity AND the build reproduces the verbatim bytes
		// exactly; otherwise the verbatim bytes. The byte-identical gate makes substitution zero-risk - the client
		// never sees anything other than the proven-good capture bytes.
		private static byte[] BuildSceneDynel(Dictionary<string, WorldObject> rows, byte[] verbatim)
		{
			if (rows == null || !SimpleDynelMessageCodec.TryParse(verbatim, out var message, out _, out _) || message.DisplayName == null || !rows.TryGetValue(message.DisplayName, out var row))
				return verbatim;

			var handle = BinaryPrimitives.ReadUInt32BigEndian(verbatim.AsSpan(4, 4));
			if (WorldObjectBuilder.TryBuild(row, handle, CreateEditorCharBuilder.EditorPlayfieldInstance, out var full) && full.Length == verbatim.Length + 8 && full.AsSpan(8).SequenceEqual(verbatim))
				return full[8..];

			return verbatim;
		}

		// The editor map's scene-prop WorldObjects, keyed by identity (display_name). Null when no DB is available
		// (the golden test), which makes BuildSceneDynel a no-op pass-through of the verbatim bytes.
		private static async Task<Dictionary<string, WorldObject>> LoadEditorSceneDynels(IDatabaseRepository database)
		{
			if (database == null)
				return null;

			var rows = new Dictionary<string, WorldObject>();
			foreach (var o in await database.GetWorldObjects(EditorMapId))
			{
				if (o.DisplayName != null)
					rows.TryAdd(o.DisplayName, o);
			}

			return rows;
		}
	}
}
